"""Recursive-descent parser for MiniDB's SQL subset.

Consumes the token list produced by ``minidb.tokenizer.tokenize`` (which
always ends with an EOF token) and builds the frozen AST nodes defined in
``minidb.types``. The statement and WHERE-expression grammars are
documented in the ``minidb.types`` module docstring:

* Precedence NOT > AND > OR; AND/OR are left-associative.
* Comparisons do not chain (``a = b = c`` is an error).
* ``IS [NOT] NULL`` produces ``IsNull(operand, negated)``.
* INSERT values must be literals, converted to Values: INTEGER token ->
  ``int``, STRING -> ``str``, TRUE/FALSE -> ``bool``, NULL -> ``None``.
* Column types in CREATE TABLE are the keywords INTEGER, TEXT, BOOLEAN,
mapped to ``ColumnType``.

Any malformed input raises ``SQLSyntaxError``.
"""

from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    i = 0
    while i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
        i += 1
    if tokens[i].type == TokenType.EOF:
        return SelectStmt("", None, None)
    stmt, i = _parse_statement(tokens, i)
    while i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
        i += 1
    if tokens[i].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after statement")
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    stmts = []
    i = 0
    while i < len(tokens):
        if tokens[i].type == TokenType.EOF:
            break
        if tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
            i += 1
            continue
        stmt, i = _parse_statement_with_semicolons(tokens, i)
        stmts.append(stmt)
    return stmts


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    expr, i = _parse_or_expr(tokens, 0)
    if i < len(tokens) and tokens[i].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after expression")
    return expr


def _parse_statement(tokens: list[Token], i: int) -> tuple[Statement, int]:
    if i >= len(tokens):
        raise SQLSyntaxError("Unexpected end of tokens")
    if tokens[i].type == TokenType.KEYWORD and tokens[i].value == "CREATE":
        return _parse_create_table_stmt(tokens, i)
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "DROP":
        return _parse_drop_table_stmt(tokens, i)
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "INSERT":
        return _parse_insert_stmt(tokens, i)
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "SELECT":
        return _parse_select_stmt(tokens, i)
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "DELETE":
        return _parse_delete_stmt(tokens, i)
    else:
        raise SQLSyntaxError(f"Unexpected token: {tokens[i]}")


def _parse_statement_with_semicolons(tokens: list[Token], i: int) -> tuple[Statement, int]:
    stmt, i = _parse_statement(tokens, i)
    while i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
        i += 1
    return stmt, i


def _parse_create_table_stmt(tokens: list[Token], i: int) -> tuple[CreateTableStmt, int]:
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected table name after CREATE TABLE")
    table_name = tokens[i].value
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR or tokens[i].value != "(":
        raise SQLSyntaxError("Expected '(' after table name in CREATE TABLE")
    i += 1
    columns = []
    while i < len(tokens) and tokens[i].type != TokenType.OPERATOR or tokens[i].value != ")":
        if tokens[i].type != TokenType.IDENTIFIER:
            raise SQLSyntaxError("Expected column name in CREATE TABLE")
        col_name = tokens[i].value
        i += 1
        if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value not in {"INTEGER", "TEXT", "BOOLEAN"}:
            raise SQLSyntaxError("Expected column type in CREATE TABLE")
        col_type = ColumnType[tokens[i].value]
        columns.append(ColumnDef(col_name, col_type))
        i += 1
        if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR:
            raise SQLSyntaxError("Expected ',' or ')' after column definition in CREATE TABLE")
        if tokens[i].value == ")":
            break
        elif tokens[i].value == ",":
            i += 1
        else:
            raise SQLSyntaxError("Expected ',' or ')' after column definition in CREATE TABLE")
    i += 1
    return CreateTableStmt(table_name, tuple(columns)), i


def _parse_drop_table_stmt(tokens: list[Token], i: int) -> tuple[DropTableStmt, int]:
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "TABLE":
        raise SQLSyntaxError("Expected 'TABLE' after DROP")
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected table name after DROP TABLE")
    table_name = tokens[i].value
    i += 1
    return DropTableStmt(table_name), i


def _parse_insert_stmt(tokens: list[Token], i: int) -> tuple[InsertStmt, int]:
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "INTO":
        raise SQLSyntaxError("Expected 'INTO' after INSERT")
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected table name after INSERT INTO")
    table_name = tokens[i].value
    i += 1
    columns = None
    if i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == "(":
        i += 1
        columns = []
        while i < len(tokens) and tokens[i].type != TokenType.OPERATOR or tokens[i].value != ")":
            if tokens[i].type != TokenType.IDENTIFIER:
                raise SQLSyntaxError("Expected column name in INSERT")
            columns.append(tokens[i].value)
            i += 1
            if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR:
                raise SQLSyntaxError("Expected ',' or ')' after column name in INSERT")
            if tokens[i].value == ")":
                break
            elif tokens[i].value == ",":
                i += 1
            else:
                raise SQLSyntaxError("Expected ',' or ')' after column name in INSERT")
        i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "VALUES":
        raise SQLSyntaxError("Expected 'VALUES' after INSERT")
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR or tokens[i].value != "(":
        raise SQLSyntaxError("Expected '(' after VALUES in INSERT")
    i += 1
    values = []
    while i < len(tokens) and tokens[i].type != TokenType.OPERATOR or tokens[i].value != ")":
        if tokens[i].type == TokenType.INTEGER:
            values.append(int(tokens[i].value))
        elif tokens[i].type == TokenType.STRING:
            values.append(tokens[i].value)
        elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "TRUE":
            values.append(True)
        elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "FALSE":
            values.append(False)
        elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "NULL":
            values.append(None)
        else:
            raise SQLSyntaxError("Expected literal value in INSERT")
        i += 1
        if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR:
            raise SQLSyntaxError("Expected ',' or ')' after value in INSERT")
        if tokens[i].value == ")":
            break
        elif tokens[i].value == ",":
            i += 1
        else:
            raise SQLSyntaxError("Expected ',' or ')' after value in INSERT")
    i += 1
    return InsertStmt(table_name, tuple(columns) if columns else None, tuple(values)), i


def _parse_select_stmt(tokens: list[Token], i: int) -> tuple[SelectStmt, int]:
    i += 1
    columns = None
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected column name or '*' after SELECT")
    if tokens[i].value == "*":
        columns = None
        i += 1
    else:
        columns = [tokens[i].value]
        i += 1
        while i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ",":
            i += 1
            if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
                raise SQLSyntaxError("Expected column name after ',' in SELECT")
            columns.append(tokens[i].value)
            i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "FROM":
        raise SQLSyntaxError("Expected 'FROM' after SELECT columns")
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected table name after FROM in SELECT")
    table_name = tokens[i].value
    i += 1
    where = None
    if i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "WHERE":
        i += 1
        where, i = _parse_expression(tokens[i:], 0)
    return SelectStmt(table_name, tuple(columns) if columns else None, where), i


def _parse_delete_stmt(tokens: list[Token], i: int) -> tuple[DeleteStmt, int]:
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "FROM":
        raise SQLSyntaxError("Expected 'FROM' after DELETE")
    i += 1
    if i >= len(tokens) or tokens[i].type != TokenType.IDENTIFIER:
        raise SQLSyntaxError("Expected table name after DELETE FROM")
    table_name = tokens[i].value
    i += 1
    where = None
    if i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "WHERE":
        i += 1
        where, i = _parse_expression(tokens[i:], 0)
    if where is None:
        where = Literal(True)
    return DeleteStmt(table_name, where), i


def _parse_or_expr(tokens: list[Token], i: int) -> tuple[Expr, int]:
    expr, i = _parse_and_expr(tokens, i)
    while i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "OR":
        i += 1
        right_expr, i = _parse_and_expr(tokens, i)
        expr = Or(expr, right_expr)
    return expr, i


def _parse_and_expr(tokens: list[Token], i: int) -> tuple[Expr, int]:
    expr, i = _parse_not_expr(tokens, i)
    while i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "AND":
        i += 1
        right_expr, i = _parse_not_expr(tokens, i)
        expr = And(expr, right_expr)
    return expr, i


def _parse_not_expr(tokens: list[Token], i: int) -> tuple[Expr, int]:
    if i >= len(tokens):
        raise SQLSyntaxError("Unexpected end of tokens")
    if tokens[i].type == TokenType.KEYWORD and tokens[i].value == "NOT":
        i += 1
        operand, i = _parse_not_expr(tokens, i)
        return Not(operand), i
    else:
        return _parse_predicate(tokens, i)


def _parse_predicate(tokens: list[Token], i: int) -> tuple[Expr, int]:
    if i >= len(tokens):
        raise SQLSyntaxError("Unexpected end of tokens")
    left, i = _parse_primary(tokens, i)
    if i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value in COMPARISON_OPS:
        op = tokens[i].value
        i += 1
        right, i = _parse_primary(tokens, i)
        return Comparison(op, left, right), i
    elif i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "IS":
        i += 1
        negated = False
        if i < len(tokens) and tokens[i].type == TokenType.KEYWORD and tokens[i].value == "NOT":
            negated = True
            i += 1
        if i >= len(tokens) or tokens[i].type != TokenType.KEYWORD or tokens[i].value != "NULL":
            raise SQLSyntaxError("Expected 'NULL' after IS [NOT] in predicate")
        i += 1
        return IsNull(left, negated), i
    else:
        raise SQLSyntaxError("Invalid predicate")


def _parse_primary(tokens: list[Token], i: int) -> tuple[Expr, int]:
    if i >= len(tokens):
        raise SQLSyntaxError("Unexpected end of tokens")
    if tokens[i].type == TokenType.INTEGER:
        return Literal(int(tokens[i].value)), i + 1
    elif tokens[i].type == TokenType.STRING:
        return Literal(tokens[i].value), i + 1
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "TRUE":
        return Literal(True), i + 1
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "FALSE":
        return Literal(False), i + 1
    elif tokens[i].type == TokenType.KEYWORD and tokens[i].value == "NULL":
        return Literal(None), i + 1
    elif tokens[i].type == TokenType.IDENTIFIER:
        return ColumnRef(tokens[i].value), i + 1
    elif tokens[i].type == TokenType.OPERATOR and tokens[i].value == "(":
        expr, j = _parse_expression(tokens[i+1:], 0)
        j += i + 1
        while j < len(tokens) and tokens[j].type != TokenType.OPERATOR or tokens[j].value != ")":
            j += 1
        if j >= len(tokens) or tokens[j].type != TokenType.OPERATOR or tokens[j].value != ")":
            raise SQLSyntaxError("Expected ')' after '(' in primary expression")
        return expr, j + 1
    else:
        raise SQLSyntaxError("Invalid primary expression")


def _parse_expression(tokens: list[Token], i: int) -> tuple[Expr, int]:
    expr, i = _parse_or_expr(tokens, i)
    return expr, i

